<script setup lang="ts">import {Head,Link,router} from '@inertiajs/vue3';import PageHeader from '@/components/Shared/PageHeader.vue';import {Button} from '@/components/ui/button';import {appConfirm} from '@/lib/appDialog';defineProps<{messages:any[]}>();async function remove(id:number){if(await appConfirm('Delete this managed message and its tracking history?',{title:'Delete message?',confirmLabel:'Delete',destructive:true}))router.delete(`/admin/message-boxes/${id}`)}</script>
<template><Head title="Message Boxes"/><div class="space-y-6 p-6"><div class="flex items-start justify-between"><PageHeader title="Message Boxes" description="Manage modal and full-width slide-in messages, targeting, schedules, and forms."/><Button as-child><Link href="/admin/message-boxes/create">Create Message</Link></Button></div><div class="overflow-hidden rounded-xl border bg-card"><table class="w-full text-sm"><thead class="bg-muted/50 text-left"><tr><th class="p-3">Message</th><th class="p-3">Style / trigger</th><th class="p-3">Pages</th><th class="p-3">Schedule</th><th class="p-3">Activity</th><th class="p-3"></th></tr></thead><tbody><tr v-for="m in messages" :key="m.id" class="border-t"><td class="p-3"><div class="font-medium">{{m.name}}</div><div class="text-xs text-muted-foreground">{{m.title||'No public title'}} · {{m.audience}}</div></td><td class="p-3"><div>{{m.presentation.replaceAll('_',' ')}}</div><div class="text-xs text-muted-foreground">{{m.trigger_type}}{{m.trigger_key?` · ${m.trigger_key}`:''}}</div></td><td class="p-3 text-xs">{{(m.page_patterns||['*']).join(', ')}}</td><td class="p-3"><span :class="m.is_current?'text-emerald-600':'text-muted-foreground'">{{m.is_current?'Live / eligible':m.is_active?'Scheduled / expired':'Inactive'}}</span><div v-if="m.show_once" class="text-xs text-muted-foreground">once per user/device</div></td><td class="p-3 text-xs">{{m.views_count}} views · {{m.submissions_count}} submissions</td><td class="p-3"><div class="flex justify-end gap-2"><Button size="sm" variant="outline" as-child><Link :href="`/admin/message-boxes/${m.id}/edit`">Edit</Link></Button><Button size="sm" variant="destructive" @click="remove(m.id)">Delete</Button></div></td></tr><tr v-if="!messages.length"><td colspan="6" class="p-10 text-center text-muted-foreground">No managed messages yet.</td></tr></tbody></table></div></div></template>
